import argparse
import json
import sys
from datetime import datetime, timezone

STATES = {"deleted", "scheduled", "retained"}
ACTIONS = {"deleted", "scheduled", "retained"}
ALGORITHMS = {"RSA", "ECDSA", "EdDSA"}
RECEIPT_STATUSES = {"pending", "complete"}
HANDLING_STATUSES = {"pending", "complete"}
REQUIRED_ROOT = {
    "receiptId", "requestReceived", "receiptIssuedAt", "subjectRef",
    "inventoryComplete", "requestHandlingStatus", "receiptStatus",
    "completionScope", "deletionCompletedAt", "stores", "signature"
}


def add(errors, message):
    errors.append(message)


def parse_timestamp(value, field, errors):
    if not isinstance(value, str):
        add(errors, f"{field}: expected ISO-8601 string")
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            raise ValueError("timezone required")
        return parsed.astimezone(timezone.utc)
    except ValueError:
        add(errors, f"{field}: invalid timestamp")
        return None


def require_string(obj, field, prefix, errors):
    value = obj.get(field)
    if not isinstance(value, str) or not value:
        add(errors, f"{prefix}{field}: expected non-empty string")
        return None
    return value


def prepare_inventory(value, errors):
    if not isinstance(value, list) or not value:
        add(errors, "config.inventory: expected non-empty string array")
        return []
    if not all(isinstance(item, str) and item for item in value):
        add(errors, "config.inventory: expected non-empty string array")
        return []
    if len(value) != len(set(value)):
        add(errors, "config.inventory: duplicate store")
        return []
    return value


def prepare_registry(value, errors):
    if not isinstance(value, dict) or not isinstance(value.get("records"), list):
        add(errors, "config.evidence: expected object with records array")
        return {}, None, None
    envelope_subject = value.get("subjectRef")
    if not isinstance(envelope_subject, str) or not envelope_subject:
        add(errors, "config.evidence.subjectRef: expected non-empty string")
        envelope_subject = None
    envelope_received = parse_timestamp(value.get("requestReceived"), "config.evidence.requestReceived", errors)
    index = {}
    for position, record in enumerate(value["records"]):
        prefix = f"config.evidence.records[{position}]"
        if not isinstance(record, dict):
            add(errors, f"{prefix}: expected object")
            continue
        record_id = require_string(record, "id", prefix + ".", errors)
        store = require_string(record, "store", prefix + ".", errors)
        action = record.get("action")
        status = record.get("status")
        if not isinstance(action, str) or action not in ACTIONS:
            add(errors, f"{prefix}.action: expected deleted, scheduled, or retained")
        if not isinstance(status, str) or status not in {"pending", "verified"}:
            add(errors, f"{prefix}.status: expected pending or verified")
        verified_at = parse_timestamp(record.get("verificationTime"), prefix + ".verificationTime", errors)
        if record_id:
            if record_id in index:
                add(errors, f"{prefix}.id: duplicate evidence id")
            else:
                index[record_id] = {
                    "store": store,
                    "action": action,
                    "status": status,
                    "time": verified_at
                }
    return index, envelope_subject, envelope_received


def result(data, errors, pending):
    status = data.get("receiptStatus") if isinstance(data, dict) else None
    handling = data.get("requestHandlingStatus") if isinstance(data, dict) else None
    completion = data.get("deletionCompletedAt") if isinstance(data, dict) else None
    overall = "invalid" if errors else ("complete" if status == "complete" else "pending")
    return {
        "valid": not errors,
        "overallStatus": overall,
        "requestHandlingStatus": handling,
        "receiptStatus": status,
        "deletionCompletedAt": completion,
        "pendingStores": pending,
        "errors": errors
    }


def validate(data, expected_inventory, evidence_registry):
    errors = []
    pending = []
    inventory = prepare_inventory(expected_inventory, errors)
    registry, evidence_subject, evidence_requested = prepare_registry(evidence_registry, errors)
    if not isinstance(data, dict):
        add(errors, "root: expected object")
        return result({}, errors, pending)

    for field in sorted(REQUIRED_ROOT - set(data.keys())):
        add(errors, f"root: missing {field}")
    for field in ("receiptId", "subjectRef"):
        if field in data:
            require_string(data, field, "", errors)

    if not isinstance(data.get("inventoryComplete"), bool):
        add(errors, "inventoryComplete: expected boolean")
    elif data.get("inventoryComplete") is not True:
        add(errors, "inventoryComplete: must be true for this supplied scope")

    handling = data.get("requestHandlingStatus")
    if not isinstance(handling, str) or handling not in HANDLING_STATUSES:
        add(errors, "requestHandlingStatus: expected pending or complete")
    receipt_status = data.get("receiptStatus")
    if not isinstance(receipt_status, str) or receipt_status not in RECEIPT_STATUSES:
        add(errors, "receiptStatus: expected pending or complete")
    scope = data.get("completionScope")
    if not isinstance(scope, str) or scope != "request-scoped-disposition":
        add(errors, "completionScope: expected request-scoped-disposition")

    requested = parse_timestamp(data.get("requestReceived"), "requestReceived", errors)
    issued = parse_timestamp(data.get("receiptIssuedAt"), "receiptIssuedAt", errors)
    if requested and issued and issued < requested:
        add(errors, "receiptIssuedAt: precedes requestReceived")
    if evidence_subject is not None and isinstance(data.get("subjectRef"), str) and data.get("subjectRef") != evidence_subject:
        add(errors, "config.evidence.subjectRef: does not match receipt subjectRef")
    if evidence_requested and requested and evidence_requested != requested:
        add(errors, "config.evidence.requestReceived: does not match receipt requestReceived")

    completion_value = data.get("deletionCompletedAt")
    completion = None
    if completion_value is not None:
        completion = parse_timestamp(completion_value, "deletionCompletedAt", errors)
        if completion and requested and completion < requested:
            add(errors, "deletionCompletedAt: precedes requestReceived")
        if completion and issued and completion > issued:
            add(errors, "deletionCompletedAt: follows receiptIssuedAt")

    stores = data.get("stores")
    if not isinstance(stores, list) or not stores:
        add(errors, "stores: expected non-empty array")
        stores = []

    seen = set()
    valid_names = []
    coverage_ok = True
    for position, store_record in enumerate(stores):
        prefix = f"stores[{position}]"
        if not isinstance(store_record, dict):
            add(errors, f"{prefix}: expected object")
            coverage_ok = False
            continue
        name = store_record.get("store")
        if not isinstance(name, str) or not name:
            add(errors, f"{prefix}.store: expected non-empty string")
            coverage_ok = False
            name = None
        elif name in seen:
            add(errors, f"{prefix}.store: duplicate store")
            coverage_ok = False
        else:
            seen.add(name)
            valid_names.append(name)

        state = store_record.get("state")
        if not isinstance(state, str) or state not in STATES:
            add(errors, f"{prefix}.state: expected deleted, scheduled, or retained")
            state = None

        refs = store_record.get("evidenceRefs")
        resolved = []
        if not isinstance(refs, list) or not refs or not all(isinstance(ref, str) and ref for ref in refs):
            add(errors, f"{prefix}.evidenceRefs: expected non-empty string array")
        else:
            for ref in refs:
                evidence = registry.get(ref)
                if evidence is None:
                    add(errors, f"{prefix}.evidenceRefs: unknown evidence id {ref}")
                    continue
                if name and evidence.get("store") != name:
                    add(errors, f"{prefix}.evidenceRefs: {ref} belongs to another store")
                    continue
                resolved.append((ref, evidence))
                evidence_time = evidence.get("time")
                if evidence_time and requested and evidence_time < requested:
                    add(errors, f"{prefix}.evidenceRefs: {ref} predates requestReceived")
                if evidence_time and issued and evidence_time > issued:
                    add(errors, f"{prefix}.evidenceRefs: {ref} verification follows receiptIssuedAt")

        if state == "deleted":
            verification = store_record.get("verification")
            if not isinstance(verification, str) or not verification:
                add(errors, f"{prefix}.verification: required for deleted")
            matching = [item for item in resolved if item[1].get("action") == "deleted" and item[1].get("status") == "verified"]
            if not matching:
                add(errors, f"{prefix}.evidenceRefs: deleted requires verified deletion evidence")
            if any(item[1].get("status") == "pending" for item in resolved):
                add(errors, f"{prefix}.evidenceRefs: deleted has contradictory pending evidence")
            if completion:
                for ref, evidence in matching:
                    if evidence.get("time") and evidence["time"] > completion:
                        add(errors, f"{prefix}.evidenceRefs: {ref} verification follows deletionCompletedAt")
        elif state == "scheduled":
            until = parse_timestamp(store_record.get("until"), prefix + ".until", errors)
            if until and issued and until <= issued:
                add(errors, f"{prefix}.until: must be after receiptIssuedAt")
            verification = store_record.get("verification")
            if not isinstance(verification, str) or not verification:
                add(errors, f"{prefix}.verification: required for scheduled")
            matching = [item for item in resolved if item[1].get("action") == "scheduled" and item[1].get("status") == "pending"]
            if not matching:
                add(errors, f"{prefix}.evidenceRefs: scheduled requires pending scheduling evidence")
            if name:
                pending.append(name)
        elif state == "retained":
            for field in ("basis", "scopeLabel"):
                value = store_record.get(field)
                if not isinstance(value, str) or not value:
                    add(errors, f"{prefix}.{field}: required for retained")
            review_at = parse_timestamp(store_record.get("reviewAt"), prefix + ".reviewAt", errors)
            if review_at and issued and review_at <= issued:
                add(errors, f"{prefix}.reviewAt: must be after receiptIssuedAt")
            legal_review = store_record.get("legalReviewComplete")
            if not isinstance(legal_review, bool):
                add(errors, f"{prefix}.legalReviewComplete: expected boolean")
            matching_verified = [item for item in resolved if item[1].get("action") == "retained" and item[1].get("status") == "verified"]
            matching_pending = [item for item in resolved if item[1].get("action") == "retained" and item[1].get("status") == "pending"]
            if legal_review is True:
                if not matching_verified:
                    add(errors, f"{prefix}.evidenceRefs: completed legal review requires verified retention evidence")
                if matching_pending:
                    add(errors, f"{prefix}.evidenceRefs: retained disposition has contradictory pending evidence")
                if completion:
                    for ref, evidence in matching_verified:
                        if evidence.get("time") and evidence["time"] > completion:
                            add(errors, f"{prefix}.evidenceRefs: {ref} verification follows deletionCompletedAt")
            else:
                if not matching_pending:
                    add(errors, f"{prefix}.evidenceRefs: incomplete legal review requires pending retention evidence")
                if name:
                    pending.append(name)

    expected_set = set(inventory)
    actual_set = set(valid_names)
    missing = sorted(expected_set - actual_set)
    extra = sorted(actual_set - expected_set)
    if missing:
        add(errors, "inventory: missing stores: " + ", ".join(missing))
        coverage_ok = False
    if extra:
        add(errors, "inventory: unexpected stores: " + ", ".join(extra))
        coverage_ok = False
    if len(valid_names) != len(inventory):
        coverage_ok = False

    signature = data.get("signature")
    if not isinstance(signature, dict):
        add(errors, "signature: expected object")
    else:
        algorithm = signature.get("alg")
        if not isinstance(algorithm, str) or algorithm not in ALGORITHMS:
            add(errors, "signature.alg: expected RSA, ECDSA, or EdDSA")
        if not isinstance(signature.get("keyId"), str) or not signature.get("keyId"):
            add(errors, "signature.keyId: expected non-empty string")
        if not isinstance(signature.get("executed"), bool):
            add(errors, "signature.executed: expected boolean")
        elif signature.get("executed") is True:
            add(errors, "signature.executed: asymmetric verification is not implemented")

    if completion_value is not None and pending:
        add(errors, "deletionCompletedAt: must be null while stores remain pending")
    if completion_value is not None and not coverage_ok:
        add(errors, "deletionCompletedAt: inventory coverage is incomplete")
    if receipt_status == "complete" and (pending or completion_value is None or not coverage_ok):
        add(errors, "receiptStatus: complete requires full inventory coverage, no pending stores, and deletionCompletedAt")
    if receipt_status == "pending" and completion_value is not None:
        add(errors, "receiptStatus: pending requires null deletionCompletedAt")

    return result(data, errors, pending)


def load_json(path):
    with open(path, encoding="utf-8") as handle:
        return json.load(handle)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("receipt")
    parser.add_argument("--inventory", default="expected_inventory.json")
    parser.add_argument("--evidence", default="evidence_registry.json")
    args = parser.parse_args()
    try:
        data = load_json(args.receipt)
        inventory = load_json(args.inventory)
        evidence = load_json(args.evidence)
        output = validate(data, inventory, evidence)
    except (OSError, json.JSONDecodeError) as exc:
        output = {
            "valid": False,
            "overallStatus": "invalid",
            "requestHandlingStatus": None,
            "receiptStatus": None,
            "deletionCompletedAt": None,
            "pendingStores": [],
            "errors": [f"input: {exc.__class__.__name__}"]
        }
    print(json.dumps(output, sort_keys=True, separators=(",", ":")))
    return 0 if output["valid"] else 1


if __name__ == "__main__":
    sys.exit(main())
